            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Death, a stopping of impressions through the senses, and of the pulling of the cords of motion, and of the ways of thought, and of service to the flesh.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Reverence the gods, and help men. Short is life.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "I consist of a little body and a soul.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Adapt yourself to the environment in which your lot has been cast, and show true love to the fellow-mortals with whom destiny has surrounded you.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "But if we judge only those things which are in our power to be good or bad, there remains no reason either for finding fault with God or standing in a hostile attitude to man.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "The only thing that isn't worthless: to live this life out truthfully and rightly. And be patient with those who don't.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "What is not good for the swarm is not good for the bee.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "How many together with whom I came into the world are already gone out of it.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "I can control my thoughts as necessary; then how can I be troubled?", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Understand however that every man is worth just so much as the things are worth about which he busies himself.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "How many, once lauded in song, are given over to the forgotten; and how many who sung their praises are clean gone long ago!", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Never let the future disturb you. You will meet it, if you have to, with the same weapons of reason which today arm you against the present.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "If you are troubled by external circumstances, it is not the circumstances that trouble you, but your own perception of them - and they are in your power to change at any time.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "No matter what anyone says or does, my task is to be good.", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Is any man afraid of change? Why what can take place without change?", Author = "Marcus Aurelius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Marcus_Aurelius", Text = "Soon you will have forgotten the world, and soon the world will have forgotten you.", Author = "Marcus Aurelius" },
